args.command:
cd ~; python3 - <<'EOF'
import workcell, re
def F():
    for _ in range(3):
        f=workcell.call("ft","read","400")
        m=re.search(r"Fz=([+-][\d.]+)",f.text)
        if m: return float(m.group(1))
    raise RuntimeError("ft fail")
def znow():
    s=workcell.call("arm","status")
    return float(re.search(r"z=([\d.]+) mm",s.text).group(1))
while F()<49.5:
    workcell.call("arm","step","-0.5")
f=F(); z=znow(); workcell.call("cam","snap","side")
print("load",f,z)
open("loads.txt","a").write(f"\n50 {f} {z}")
EOF
cat loads.txt

